UPDATE t_csys_teaching_plan
root_plan_id = #{rootPlanId}, source_course_id = #{sourceCourseId}, plan_type = #{planType}, version = #{version}, current_flag = #{currentFlag}, enabled_term = #{enabledTerm}, status = #{status}, source_course_name = #{sourceCourseName}, source_course_code = #{sourceCourseCode}, source_course_en_name = #{sourceCourseEnName}, source_hours = #{sourceHours}, source_teach_hours = #{sourceTeachHours}, source_practice_hours = #{sourcePracticeHours}, source_credit = #{sourceCredit}, score_rule = #{scoreRule}, file_id = #{fileId}, file_name = #{fileName}, download_url = #{downloadUrl}, preview_url = #{previewUrl}, last_modifier = #{lastModifier}, last_modified_time = #{lastModifiedTime}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT

FROM t_csys_teaching_plan

    sysflag = 0
    AND source_course_id = #{sourceCourseId}
    AND plan_type = #{planType}
    AND status = #{status}
    AND current_flag = #{currentFlag}

ORDER BY id DESC

SELECT c2.source_id AS courseId, GROUP_CONCAT(DISTINCT NULLIF(ts.education_level, '') SEPARATOR '、') AS educationLevel, GROUP_CONCAT(DISTINCT sm.name SEPARATOR '、') AS majorName, GROUP_CONCAT(DISTINCT NULLIF(c2.course_attr, '') SEPARATOR '、') AS courseAttr, GROUP_CONCAT(DISTINCT NULLIF(c2.course_Module, '') SEPARATOR '、') AS courseModule, GROUP_CONCAT(DISTINCT NULLIF(c2.location, '') SEPARATOR '、') AS location FROM t_csys_course c2 LEFT JOIN t_csys_training_scheme_course_schedule tcs ON tcs.course_id = c2.id LEFT JOIN t_csys_training_scheme ts ON ts.id = tcs.scheme_id AND ts.sysflag = 0 LEFT JOIN t_csys_std_major sm ON sm.id = ts.major_id WHERE c2.sysflag = 0 AND c2.source_id IN
#{id}
GROUP BY c2.source_id

SELECT course_id AS courseId, semester_Schedule AS semesterSchedule, spring_Autumn AS springAutumn, time_Week AS timeWeek, unit AS unit FROM t_csys_course_ref_schedule WHERE course_id IN
#{id}
ORDER BY course_id, id
